package main

import "fmt"

// User demonstrates stack vs heap allocation
type User struct {
	ID   int
	Name string
}

// NewUserHeap escapes to Heap: Address of locally created struct is returned outside the function frame.
// The compiler's escape analysis moves 'u' from stack to heap.
func NewUserHeap(name string) *User {
	u := User{ID: 1, Name: name} // ESCAPES TO HEAP
	return &u
}

// NewUserStack stays on Stack: Struct is returned by value (copied across stack frame).
// Zero GC overhead.
func NewUserStack(name string) User {
	u := User{ID: 2, Name: name} // STAYS ON STACK
	return u
}

func main() {
	fmt.Println("=== 01: Go Runtime, Memory & Escape Analysis ===")

	// 1. Heap allocated user
	heapUser := NewUserHeap("Alice (Heap)")
	fmt.Printf("Heap User: %+v, Pointer: %p\n", heapUser, heapUser)

	// 2. Stack allocated user
	stackUser := NewUserStack("Bob (Stack)")
	fmt.Printf("Stack User: %+v\n", stackUser)

	// TIP: Run escape analysis compiler flag in terminal:
	// go build -gcflags="-m -m" main.go
}

