package main

import (
	"fmt"
	"unsafe"
)

func main() {
	fmt.Println("=== 04: Memory Representation & Headers ===")

	// String Memory Layout (16 bytes on 64-bit architecture: Pointer [8B] + Length [8B])
	str := "Hello, Go!"
	fmt.Printf("String size in memory: %d bytes, Length: %d chars\n", unsafe.Sizeof(str), len(str))

	// Slice Memory Layout (24 bytes on 64-bit architecture: Pointer [8B] + Length [8B] + Capacity [8B])
	slice := []int{10, 20, 30, 40}
	fmt.Printf("Slice header size: %d bytes, Length: %d, Capacity: %d\n", unsafe.Sizeof(slice), len(slice), cap(slice))

	// Rune vs Byte
	var charRune rune = 'G' // int32 (4 bytes, Unicode code point)
	var charByte byte = 'A' // uint8 (1 byte, ASCII)
	fmt.Printf("Rune size: %d bytes (%c) | Byte size: %d bytes (%c)\n", unsafe.Sizeof(charRune), charRune, unsafe.Sizeof(charByte), charByte)
}

package main

import (
	"encoding/json"
	"fmt"
)

type BaseEntity struct {
	ID        string `json:"id"`
	CreatedAt int64  `json:"created_at"`
}

// Composition via Struct Embedding (Promotes fields and methods)
type UserAccount struct {
	BaseEntity        // Embedded struct
	Username   string `json:"username"`
	Email      string `json:"email"`
	IsActive   bool   `json:"is_active"`
}

func main() {
	fmt.Println("=== 06: Maps, Structs & Composition ===")

	// 1. Hash Maps & Comma-OK Idiom
	scores := make(map[string]int)
	scores["Alice"] = 95
	scores["Bob"] = 0 // Valid score of 0

	// Check if key exists or if value is default zero value
	if score, ok := scores["Bob"]; ok {
		fmt.Printf("Bob exists with score: %d\n", score)
	}

	if _, ok := scores["Charlie"]; !ok {
		fmt.Println("Charlie does not exist in scores map!")
	}

	delete(scores, "Alice") // Safe delete

	// 2. Struct Composition & Embedding
	account := UserAccount{
		BaseEntity: BaseEntity{ID: "usr_101", CreatedAt: 1725000000},
		Username:   "navnath",
		Email:      "navnath@example.com",
		IsActive:   true,
	}

	// Accessing promoted fields directly
	fmt.Printf("Account ID: %s | Username: %s\n", account.ID, account.Username)

	// JSON serialization
	jsonData, _ := json.MarshalIndent(account, "", "  ")
	fmt.Printf("JSON Representation:\n%s\n", string(jsonData))
}

