import "fmt"

// SafeDivision demonstrates panic and recover handling
func SafeDivision(a, b int) (result int, err error) {
	defer func() {
		if r := recover(); r != nil {
			err = fmt.Errorf("recovered from panic: %v", r)
		}
	}()

	return a / b, nil
}

func main() {
	fmt.Println("=== 07: Control Flow, Defer Stack & Panic/Recover ===")

	// 1. Defer executes in LIFO (Last-In-First-Out) order
	fmt.Println("Scheduling deferred calls...")
	defer fmt.Println("Deferred 1 (First scheduled, last executed)")
	defer fmt.Println("Deferred 2")
	defer fmt.Println("Deferred 3 (Last scheduled, first executed)")

	// 2. Type Switch
	var mystery interface{} = "Go Master"
	switch v := mystery.(type) {
	case int:
		fmt.Printf("Integer: %d\n", v)
	case string:
		fmt.Printf("String: %s (Length %d)\n", v, len(v))
	default:
		fmt.Println("Unknown type")
	}

	// 3. Safe Recovery from Panic
	_, err := SafeDivision(10, 0)
	if err != nil {
		fmt.Printf("Handled Panic gracefully: %v\n", err)
	}
}

