import "fmt"

type Wallet struct {
	Balance int
}

// Value Semantics: Operates on a copy. Caller's balance remains unchanged.
func DepositValue(w Wallet, amount int) {
	w.Balance += amount
}

// Pointer Semantics: Operates on the original memory location.
func DepositPointer(w *Wallet, amount int) {
	w.Balance += amount
}

func main() {
	fmt.Println("=== 08: Pointers & Value vs Pointer Semantics ===")

	w := Wallet{Balance: 100}

	DepositValue(w, 50)
	fmt.Printf("After Value Deposit   : %d (No change!)\n", w.Balance)

	DepositPointer(&w, 50)
	fmt.Printf("After Pointer Deposit : %d (Updated!)\n", w.Balance)
}

