import "fmt"

// CustomError implements error interface
type CustomError struct{}

func (c *CustomError) Error() string {
	return "custom error occurred"
}

// Returns a typed nil pointer wrapped inside an interface
func GetError(trigger bool) error {
	var err *CustomError = nil
	if trigger {
		err = &CustomError{}
	}
	// TRAP: When returning 'err', Go wraps the type (*CustomError) and value (nil) into an interface header.
	// The interface is NOT nil because its Type field is non-nil!
	return err
}

func main() {
	fmt.Println("=== 09: Interfaces & The Infamous nil Interface Trap ===")

	err := GetError(false)

	// Interview Classic: Is err == nil?
	if err != nil {
		fmt.Printf("⚠️ THE NIL INTERFACE TRAP TRIGGERED! err is NOT nil because interface has type info: (type=%T, value=%v)\n", err, err)
	} else {
		fmt.Println("err is nil")
	}

	fmt.Println("\nRule: Always return explicit 'nil' rather than a nil pointer of concrete type!")
}

