import "fmt"

// Number constraint combining numeric types
type Number interface {
	~int | ~int64 | ~float64
}

// Sum works for any Number type
func Sum[T Number](items []T) T {
	var total T
	for _, item := range items {
		total += item
	}
	return total
}

// Generic Stack Data Structure
type Stack[T any] struct {
	elements []T
}

func (s *Stack[T]) Push(val T) {
	s.elements = append(s.elements, val)
}

func (s *Stack[T]) Pop() (T, bool) {
	if len(s.elements) == 0 {
		var zero T
		return zero, false
	}
	val := s.elements[len(s.elements)-1]
	s.elements = s.elements[:len(s.elements)-1]
	return val, true
}

func main() {
	fmt.Println("=== 10: Generics (Go 1.18+) ===")

	intSum := Sum([]int{1, 2, 3, 4, 5})
	floatSum := Sum([]float64{1.5, 2.5, 3.0})
	fmt.Printf("Int Sum: %d | Float Sum: %.2f\n", intSum, floatSum)

	stringStack := Stack[string]{}
	stringStack.Push("First")
	stringStack.Push("Second")
	val, _ := stringStack.Pop()
	fmt.Printf("Popped from Generic Stack: %s\n", val)
}

