import (
	"errors"
	"fmt"
)

// Sentinel Error
var ErrNotFound = errors.New("resource not found")

func FetchUser(id int) error {
	if id == 404 {
		// Error wrapping with %w
		return fmt.Errorf("database query failed for id %d: %w", id, ErrNotFound)
	}
	return nil
}

func main() {
	fmt.Println("=== 11: Modern Error Architecture (%w, errors.Is, errors.As) ===")

	err := FetchUser(404)
	if err != nil {
		fmt.Printf("Full wrapped error: %v\n", err)

		// errors.Is checks anywhere in error chain
		if errors.Is(err, ErrNotFound) {
			fmt.Println("✔ Root cause detected: ErrNotFound!")
		}
	}
}

