	"time"
)

func worker(id int, wg *sync.WaitGroup) {
	defer wg.Done()
	fmt.Printf("Goroutine %d executing on OS Thread\n", id)
	time.Sleep(50 * time.Millisecond)
}

func main() {
	fmt.Println("=== 12: Concurrency & The GMP Scheduler ===")
	fmt.Printf("Logical Processors (P): %d\n", runtime.GOMAXPROCS(0))

	var wg sync.WaitGroup
	for i := 1; i <= 5; i++ {
		wg.Add(1)
		go worker(i, &wg)
	}

	wg.Wait()
	fmt.Println("All goroutines completed!")
}

package main

import (
	"fmt"
	"sync"
	"time"
)

func main() {
	fmt.Println("=== 13: Channels, Select & Sync Primitives ===")

	// 1. Buffered Channel with Select Timeout
	ch := make(chan string, 2)
	ch <- "Job 1"
	ch <- "Job 2"

	select {
	case msg := <-ch:
		fmt.Printf("Received: %s\n", msg)
	case <-time.After(100 * time.Millisecond):
		fmt.Println("Timed out waiting for channel!")
	}

	// 2. sync.RWMutex (Multiple readers, single exclusive writer)
	var mu sync.RWMutex
	data := map[string]int{"hits": 0}

	// Writer
	mu.Lock()
	data["hits"] += 10
	mu.Unlock()

	// Reader
	mu.RLock()
	val := data["hits"]
	mu.RUnlock()
	fmt.Printf("RWMutex protected hits: %d\n", val)

	// 3. sync.Once (Guaranteed single execution for singleton configs)
	var once sync.Once
	for i := 0; i < 3; i++ {
		once.Do(func() {
			fmt.Println("sync.Once: Initialized singleton resource exactly once!")
		})
	}
}

