import (
	"context"
	"fmt"
	"time"
)

func LongRunningOperation(ctx context.Context) error {
	select {
	case <-time.After(200 * time.Millisecond):
		return nil
	case <-ctx.Done():
		return ctx.Err()
	}
}

func main() {
	fmt.Println("=== 14: Context Cancellation & Timeout Trees ===")

	// Context with 100ms Timeout (will cancel before operation finishes)
	ctx, cancel := context.WithTimeout(context.Background(), 100*time.Millisecond)
	defer cancel()

	err := LongRunningOperation(ctx)
	if err != nil {
		fmt.Printf("Operation aborted by context: %v\n", err)
	} else {
		fmt.Println("Operation succeeded!")
	}
}

