package main

import (
	"encoding/json"
	"fmt"
	"net/http"
	"time"
)

// LoggingMiddleware wraps handlers with timing
func LoggingMiddleware(next http.Handler) http.Handler {
	return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		start := time.Now()
		next.ServeHTTP(w, r)
		fmt.Printf("[%s] %s %s took %v\n", time.Now().Format(time.RFC3339), r.Method, r.URL.Path, time.Since(start))
	})
}

func HealthHandler(w http.ResponseWriter, r *http.Request) {
	w.Header().Set("Content-Type", "application/json")
	json.NewEncoder(w).Encode(map[string]interface{}{
		"status":    "healthy",
		"timestamp": time.Now().Unix(),
	})
}

func main() {
	fmt.Println("=== 16: Production HTTP Web Server & Middleware ===")

	mux := http.NewServeMux()
	mux.HandleFunc("/health", HealthHandler)

	server := &http.Server{
		Addr:         ":8080",
		Handler:      LoggingMiddleware(mux),
		ReadTimeout:  5 * time.Second,
		WriteTimeout: 10 * time.Second,
		IdleTimeout:  120 * time.Second,
	}

	fmt.Printf("Server configured on port 8080 with timeouts. Ready for production!\n")
	_ = server
}

